    /// #1771 (5-agent vote 4d3ea1c5) — postgres parity for the SQLite
    /// `archive_memory_then_restore_preserves_links_1771` test. Archiving a
    /// memory via `archive_by_ids` snapshots its `memory_links` into
    /// `archived_memory_links` BEFORE the cascade delete reaps them, and
    /// `archive_restore` re-inserts every preserved edge whose both
    /// endpoints exist. Gated on `AI_MEMORY_TEST_POSTGRES_URL`; skips
    /// cleanly when unset so the default offline `cargo test` flow is
    /// unaffected. CI's Postgres-gate sets the env and runs this for real.
    #[tokio::test]
    async fn archive_restore_preserves_links_pg_1771() {
        let Some(url) = postgres_url() else {
            eprintln!("skip: AI_MEMORY_TEST_POSTGRES_URL not set");
            return;
        };
        let store = PostgresStore::connect(&url).await.expect("connect");
        let ctx = CallerContext::for_agent("ai:sal-test");
        let unique = uuid::Uuid::new_v4();
        let ns = format!("amlinks-1771-{unique}");
        let a_id = format!("aml-a-{unique}");
        let b_id = format!("aml-b-{unique}");
        let a = sample_memory(&a_id, &ns, "aml-a", "edge endpoint a");
        let b = sample_memory(&b_id, &ns, "aml-b", "edge endpoint b");
        store.store(&ctx, &a).await.expect("store a");
        store.store(&ctx, &b).await.expect("store b");

        // Create the A -> B edge.
        let link = crate::models::MemoryLink {
            source_id: a_id.clone(),
            target_id: b_id.clone(),
            relation: crate::models::MemoryLinkRelation::RelatedTo,
            created_at: chrono::Utc::now().to_rfc3339(),
            signature: None,
            observed_by: None,
            valid_from: None,
            valid_until: None,
            attest_level: None,
            source_cid: None,
            target_cid: None,
        };
        store.link(&ctx, &link).await.expect("create link");

        // Sanity: A has the edge before archiving.
        let before = store
            .get_links_for_anchor(&a_id)
            .await
            .expect("get_links_for_anchor before");
        assert!(
            before
                .iter()
                .any(|l| l.source_id == a_id && l.target_id == b_id),
            "A should have the A->B edge before archive"
        );

        // Archive A (explicit archive-by-id path) — the cascade delete
        // reaps the edge from `memory_links`, but the snapshot must have
        // preserved it into `archived_memory_links` in the same tx.
        let moved = store
            .archive_by_ids(&ctx, std::slice::from_ref(&a_id), Some("test-1771"))
            .await
            .expect("archive_by_ids");
        assert_eq!(moved, 1, "exactly one memory archived");

        // Restore A — the preserved edge must be re-inserted because both
        // endpoints (A restored, B never archived) currently exist.
        let restored = store
            .archive_restore(&ctx, &a_id)
            .await
            .expect("archive_restore");
        assert!(restored, "archive_restore must report success");

        let after = store
            .get_links_for_anchor(&a_id)
            .await
            .expect("get_links_for_anchor after");
        assert!(
            after
                .iter()
                .any(|l| l.source_id == a_id && l.target_id == b_id),
            "A->B edge must be preserved across archive_by_ids + archive_restore"
        );
    }

    /// #2310 — postgres `lease_acquire` first-acquire mutual exclusion.
    /// `SELECT ... FOR UPDATE` cannot lock an ABSENT row, so two concurrent
    /// first-acquires both read `None`; pre-fix the unconditional
    /// `ON CONFLICT (action_id) DO UPDATE` then let the LOSER silently steal
    /// the winner's just-committed live lease and BOTH callers returned `Ok`.
    /// The fix makes the upsert self-guarding (same-holder or expired only)
    /// and maps `rows_affected() == 0` to the typed `Conflict`. This test
    /// races 8 concurrent first-acquires with distinct holders and asserts
    /// exactly ONE `Ok`, and that the surviving row belongs to that winner.
    /// Skips cleanly when `AI_MEMORY_TEST_POSTGRES_URL` unset.
    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn lease_acquire_concurrent_first_acquire_single_winner_2310() {
        let Some(url) = postgres_url() else {
            eprintln!("skip: AI_MEMORY_TEST_POSTGRES_URL not set");
            return;
        };
        let store = PostgresStore::connect(&url).await.expect("connect");
        let ctx = CallerContext::for_agent("ai:sal-test");
        let unique = uuid::Uuid::new_v4();
        let ns = format!("lease-2310-{unique}");
        let aid = format!("lease-2310-act-{unique}");
        let action = crate::models::Action {
            id: aid.clone(),
            namespace: ns,
            kind: "test.lease-race".to_string(),
            state: crate::models::ActionState::Pending,
            title: "lease 2310 race target".to_string(),
            payload: serde_json::json!({}),
            priority: 5,
            agent_id: Some("ai:sal-test".to_string()),
            claimed_by: None,
            vector_clock: serde_json::json!({}),
            metadata: serde_json::json!({}),
            created_at: 1_700_000_000,
            updated_at: 1_700_000_000,
        };
        store
            .action_create(&ctx, &action)
            .await
            .expect("action_create");

        let now = 1_700_100_000_i64;
        let expires = now + 60;
        let mut handles = Vec::new();
        for i in 0..8 {
            let store = store.clone();
            let ctx = ctx.clone();
            let aid = aid.clone();
            handles.push(tokio::spawn(async move {
                let holder = format!("holder-{i}");
                store
                    .lease_acquire(&ctx, &aid, &holder, now, expires)
                    .await
                    .map(|l| l.holder)
            }));
        }
        let mut winners = Vec::new();
        for h in handles {
            match h.await.expect("join lease task") {
                Ok(holder) => winners.push(holder),
                Err(StoreError::Conflict { .. }) => {}
                Err(e) => panic!("unexpected lease_acquire error: {e}"),
            }
        }
        assert_eq!(
            winners.len(),
            1,
            "exactly one concurrent first-acquire may win the lease (got {winners:?})"
        );
        let (holder_row,): (String,) =
            sqlx::query_as("SELECT holder FROM leases WHERE action_id = $1")
                .bind(&aid)
                .fetch_one(&store.pool)
                .await
                .expect("lease row present");
        assert_eq!(
            holder_row, winners[0],
            "the surviving leases row must belong to the single winner"
        );
        // Cleanup — cascade removes the lease row with the action.
        let _ = sqlx::query("DELETE FROM actions WHERE id = $1")
            .bind(&aid)
            .execute(&store.pool)
            .await;
    }

